def consistency_across_runs(per_run: Dict[float, Dict[str, dict]]) -> Dict:
    """
    Para cada problema, mira si pasa consistentemente a traves de los
    4 niveles de ruido. Devuelve:
      - always_pass, always_fail, mixed (count)
      - per_sigma_pass_lists: {sigma: {task_id: bool}}
    """
    sigmas = sorted(per_run.keys())
    per_task: Dict[str, Dict[float, bool]] = {}
    for sigma, records in per_run.items():
        for r in records:
            per_task.setdefault(r["task_id"], {})[sigma] = bool(r["passed"])

    always_pass = sum(1 for d in per_task.values() if all(d.values()))
    always_fail = sum(1 for d in per_task.values() if not any(d.values()))
    mixed = sum(1 for d in per_task.values()
                if any(d.values()) and not all(d.values()))

    # tasa de consistencia pairwise entre sigmas
    pw: Dict[str, float] = {}
    for i, s1 in enumerate(sigmas):
        for s2 in sigmas[i + 1:]:
            agree = sum(1 for d in per_task.values()
                        if d[s1] == d[s2])
            pw[f"agreement_{s1}_vs_{s2}"] = agree / len(per_task)
    return {
        "n_problems": len(per_task),
        "always_pass": always_pass,
        "always_fail": always_fail,
        "mixed_outcome": mixed,
        "pairwise_agreement": pw,
        "per_sigma_pass": {str(s): sum(1 for d in per_task.values() if d[s])
                           for s in sigmas},
    }

def inject_noise(model: TopoGPT2, sigma: float, seed: int) -> Dict[str, int]:
    """
    Anade N(0, sigma) a TODOS los kernels espectrales (kr_*, ki_*).
    Retorna un dict con conteo de tensores ruidosos y de parametros
    modificados.
    """
    if sigma <= 0.0:
        return {"tensors_noised": 0, "params_noised": 0}
    g = torch.Generator(device="cpu").manual_seed(seed)
    n_tensors = 0
    n_params = 0
    with torch.no_grad():
        for mod in model.modules():
            if isinstance(mod, QuaternionSpectralLayer):
                for c in ("w", "x", "y", "z"):
                    for prefix in ("kr_", "ki_"):
                        pname = f"{prefix}{c}"
                        if hasattr(mod, pname):
                            p = getattr(mod, pname)
                            noise = torch.randn(
                                p.shape, generator=g, dtype=torch.float32
                            ) * sigma
                            p.add_(noise.to(p.dtype))
                            n_tensors += 1
                            n_params += p.numel()
    return {"tensors_noised": n_tensors, "params_noised": n_params}

def extract_candidate(prompt: str, completion: str) -> str:
    if completion.startswith(prompt):
        body = completion[len(prompt):]
    else:
        body = completion
    code = prompt + body
    lines = code.splitlines(keepends=True)
    out: List[str] = []
    started = False
    for i, line in enumerate(lines):
        out.append(line)
        if started and not line.startswith((" ", "\t")) and (
            line.lstrip().startswith("def ") or line.lstrip().startswith("class ")
            or line.lstrip().startswith("if __name__")
        ):
            out.pop()
            break
        if not started:
            if i >= 1 and line.lstrip() == '"""':
                started = True
            elif i >= 1 and line.startswith("def ") and i + 1 < len(lines):
                if not lines[i + 1].lstrip().startswith(('"""', "'", '"')):
                    started = True
    return "".join(out)

def run_test(problem: dict, candidate_src: str) -> Tuple[bool, str]:
    entry_point = problem["entry_point"]
    program = candidate_src + "\n" + problem["test"] + f"\ncheck({entry_point})\n"
    ns: Dict[str, object] = {}
    out, err = io.StringIO(), io.StringIO()
    try:
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            exec(compile(program, "<humaneval-repair>", "exec"), ns, ns)
        return True, "ok"
    except Exception as exc:
        tb = traceback.format_exc(limit=2)
        return False, f"{type(exc).__name__}: {exc}\n{tb}".strip()

def build_repair_prompt(prompt: str, candidate: str, err: str, entry_point: str) -> str:
    # Trim candidate to first ~25 lines to avoid prompt bloat
    cand_lines = candidate.splitlines()
    if len(cand_lines) > 30:
        candidate = "\n".join(cand_lines[:30]) + "\n    # ... (truncated)"
    err_short = (err or "").split("\n")[0][:200]
    return (
        f"{prompt}\n"
        f"# previous attempt:\n{candidate}\n"
        f"# the test failed with:\n# {err_short}\n"
        f"# fix and rewrite the body of {entry_point}:\n"
    )


@torch.no_grad()

def pass_at_k(n, c, k):
    if n - c < k:
        return 1.0
    return 1.0 - math.prod(1.0 - k / (n - i) for i in range(c)) if c > 0 else 0.0

