            if not torch.isfinite(probs).all() or probs.sum().item() <= 0:
                break
            next_tok = torch.multinomial(probs, 1, generator=generator)

        token_id = int(next_tok.item())
        if constraint is not None:
            if not constraint.accept(token_id):
