def _request_constraint(req: Any) -> GrammarConstraint | None:
    if req.auto_continue and (
        req.response_format is not None or req.so_args is not None
    ):
        raise HTTPException(
            status_code=400,
            detail="auto_continue cannot be combined with structured output",
        )
    try:
        return constraint_from_request(
            _MODEL.tokenizer, req.response_format, req.so_args
        )
    except StructuredOutputError as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc

def _build_chat_prompt(messages: list[Message]) -> str:
    # if any message carries tools/reasoning content,
    # render via the shared chat template; else legacy last-user fallback.
    try:
        from .chat import apply_chat_template as _tpl
        dicts = [m.model_dump() for m in messages]
        if any(isinstance(d.get("content"), list) or d.get("tools")
               for d in dicts):
            norm = [{"role": d.get("role", "user"),
                     "content": _extract_text(d.get("content", ""))} for d in dicts]
            return _tpl(norm)
    except Exception:
        pass
    for msg in reversed(messages):
        if msg.role == "user":
            return _extract_text(msg.content)
    return ""

def _extract_text(content: str | list[dict] | Any) -> str:
    if isinstance(content, str):
        return content[-MAX_CONTENT_LEN:]
    if isinstance(content, list):
        texts: list[str] = []
        for block in content:
            if isinstance(block, dict):
                t = block.get("text", "")
                if t:
                    texts.append(str(t))
        return " ".join(texts)[-MAX_CONTENT_LEN:]
    return str(content)[-MAX_CONTENT_LEN:]

async def _stream_completion(
    prompt: str, max_tokens: int, temperature: float,
    top_k: int, repetition_penalty: float, stop: list[str],
    auto_continue: bool = False, max_continuations: int = 3,
    seed: int | None = None, constraint: GrammarConstraint | None = None,
):
    t0 = int(time.time())
    short_id = _short_id()
    for chunk_text in _MODEL.stream_complete(
        prompt, max_new_tokens=max_tokens, temperature=temperature,
        top_k=top_k, repetition_penalty=repetition_penalty, stop=stop,
        auto_continue=auto_continue, max_continuations=max_continuations,
        seed=seed, constraint=constraint,
    ):
        data = {
            "id": f"cmpl-{short_id}",
            "object": "text_completion",
            "created": t0,
            "model": "topogpt3",
            "choices": [
                {"text": chunk_text, "index": 0, "logprobs": None, "finish_reason": None}
            ],
        }
        yield f"data: {json.dumps(data)}\n\n"
    data = {
        "id": f"cmpl-{short_id}",
        "object": "text_completion",
        "created": t0,
        "model": "topogpt3",
        "choices": [
            {"text": "", "index": 0, "logprobs": None, "finish_reason": "stop"}
        ],
    }
    yield f"data: {json.dumps(data)}\n\n"
    yield "data: [DONE]\n\n"

