def pre_processing_chat(conversations: List[Dict[str, Any]],
                        add_system_ratio: float = 0.2) -> List[Dict[str, Any]]:
    """Randomly prepend a system prompt (skip when tools present)."""
    if any(c.get("tools") for c in conversations):
        return conversations
    if conversations and conversations[0].get("role") != "system":
        if random.random() < add_system_ratio:
            return [{"role": "system", "content": random.choice(SYSTEM_PROMPTS)}] + conversations
    return conversations

def _fmt_tool_defs(tools: Optional[List[Dict[str, Any]]]) -> str:
    if not tools:
        return ""
    lines = ["# Tools", "", "You may call these tools with:"]
    lines.append(f"{TOOL_CALL_OPEN}{{\"name\": ..., \"arguments\": ...}}{TOOL_CALL_CLOSE}")
    for t in tools:
        fn = t.get("function", t) if isinstance(t, dict) else {}
        lines.append(f"- {fn.get('name')}: {fn.get('description', '')}")
    return "\n".join(lines) + "\n\n"

def parse_tool_calls(text: str) -> List[Dict[str, Any]]:
    calls = []
    for m in TOOL_CALL_RE.findall(text):
        try:
            calls.append(json.loads(m.strip()))
        except Exception:
            continue
    return calls

def parse_thinking(text: str) -> Dict[str, str]:
    m = THINK_RE.search(text)
    if not m:
        return {"thinking": "", "answer": text}
    return {"thinking": m.group(1).strip(),
            "answer": THINK_RE.sub("", text).strip()}

def split_reasoning_content(text: str) -> Dict[str, Any]:
    """Split generated text into reasoning_content / content / tool_calls (API)."""
    th = parse_thinking(text)
    tcs = parse_tool_calls(text)
    content = th["answer"]
    for m in TOOL_CALL_RE.finditer(text):
        content = content.replace(m.group(0), "")
    return {"reasoning_content": th["thinking"], "content": content.strip(),
            "tool_calls": tcs}

def _count_unclosed_brackets(text: str) -> int:
    stack: List[str] = []
    for ch in text:
        if ch in _OPENERS:
            stack.append(ch)
        elif ch in _CLOSERS:
            if stack and _CLOSING.get(ch) == stack[-1]:
                stack.pop()
    return len(stack)

def _count_unclosed_fences(text: str) -> int:
    fences = 0
    for line in text.splitlines():
        m = _CODE_FENCE_RE.match(line.strip())
        if m:
            fences += 1
    return fences % 2  # 0 = balanced, 1 = unclosed

def is_response_complete(text: str, min_chars: int = 10) -> bool:
    """Heuristic to decide whether a model response looks finished.

    Returns True when the response seems naturally complete (no need to
    continue), False when it appears truncated and continuation may help.
    """
    stripped = text.rstrip()

    if len(stripped) < min_chars:
        return False

    if _count_unclosed_fences(stripped):
        return False

    if _count_unclosed_brackets(stripped) > 0:
        return False

    if not stripped:
        return False

    last_ch = stripped[-1]
    if last_ch in {":", ",", ";", "\\"}:
        return False

    if last_ch in {"\n", ".", "!", "?", ")", "}", "]", "`", '"', "'"}:
        return True

    return True

