def agent_reward(text: str, gt: str, used_tools: bool) -> float:
    r = 0.0
    if used_tools:
        r += 0.5
    if gt and gt in text:
        r += 2.5 * (len(gt) / max(len(text), 1))
    if "</think>" in text:
        r += 0.5
    r -= rep_penalty(text)
    return max(min(r, 3.0), -3.0)

def load_model(checkpoint, device):
    cfg = TopoGPT2Config()
    m = TopoGPT2(cfg)
    sf = os.path.join(checkpoint, "model.safetensors")
    if os.path.exists(sf):
        m.load_state_dict(load_file(sf, device="cpu"), strict=False)
    return m.to(device)

def Logger(content, quiet: bool = False):
    if not quiet and (not dist.is_initialized() or dist.get_rank() == 0):
        print(content, flush=True)

def get_lr(current_step: int, total_steps: int, lr: float) -> float:
    total_steps = max(total_steps, 1)
    return lr * (0.1 + 0.45 * (1 + math.cos(math.pi * current_step / total_steps)))

def __iter__(self):
    batch, skipped = [], 0
    for idx in self.sampler:
        batch.append(idx)
        if len(batch) == self.batch_size:
            if skipped < self.skip_batches:
                skipped += 1
                batch = []
                continue
            yield batch
            batch = []
    if batch and skipped >= self.skip_batches:
        yield batch

def __len__(self):
    total = (len(self.sampler) + self.batch_size - 1) // self.batch_size
    return max(0, total - self.skip_batches)
